import{_ as e,o as l,c as r,a2 as i}from"./chunks/framework.BEUshCVJ.js";const g=JSON.parse('{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"zh/reference/changelog.md","filePath":"zh/reference/changelog.md","lastUpdated":1793025781000}'),o={name:"zh/reference/changelog.md"};function t(n,a,h,s,d,u){return l(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h1><p>MeetCue 的重要变更记录。版本号遵循<a href="https://semver.org/lang/zh-CN/" target="_blank" rel="noreferrer">语义化版本</a>。</p><h2 id="未发布" tabindex="-1">未发布 <a class="header-anchor" href="#未发布" aria-label="Permalink to &quot;未发布&quot;">​</a></h2><h2 id="_0-2-3-—-2026-10-26" tabindex="-1">0.2.3 — 2026-10-26 <a class="header-anchor" href="#_0-2-3-—-2026-10-26" aria-label="Permalink to &quot;0.2.3 — 2026-10-26&quot;">​</a></h2><h3 id="新增" tabindex="-1">新增 <a class="header-anchor" href="#新增" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>模拟面试窗口改为四步引导：声音检查（含实时电平）、选题目、确认题目、开始练习。每一步都会写明下一步要做什么，练习过程中也会提示当前该做什么。</li><li>新增 <strong>再问一遍</strong>：从头重读当前这道题，练习窗口和面板上都有。</li><li>可以在声音检查这一步按语言选择朗读问题的语音，并点 <strong>试听</strong> 试听。朗读语速也移到了这里。</li></ul><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>问题有时读到一半就停：咳嗽、“嗯”，或者把问题本身的回声听错一个词，都会被当成用户开始回答。现在必须是真正的说话才会打断，练习设置里的口头禅一律不算。</li></ul><h2 id="_0-2-2-—-2026-10-26" tabindex="-1">0.2.2 — 2026-10-26 <a class="header-anchor" href="#_0-2-2-—-2026-10-26" aria-label="Permalink to &quot;0.2.2 — 2026-10-26&quot;">​</a></h2><h3 id="新增-1" tabindex="-1">新增 <a class="header-anchor" href="#新增-1" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>模拟面试更容易找到：托盘菜单靠上位置新增 <strong>模拟面试…</strong>，空闲面板上有入口链接，也可以从 <strong>设置 › 通用</strong> 和设置向导最后一步打开。窗口最上方有分步的 <strong>流程</strong> 说明。</li><li>练习的播放方式改为 <strong>问题语音转文字</strong> 开关：开启（默认）时像会议一样把朗读的问题转成文字；关闭时问题文本直接交给要点模型。两种情况下问题都会朗读出来。<strong>识别我的回答</strong> 改名为 <strong>我的回答语音转文字</strong>。</li><li>内置软件工程和网络安全与 AI 方向的示例面试，包括问题列表和面试字幕，一键即可载入。可作为会前资料的示例职位描述放在 <code>samples/materials</code>。</li><li>新增<a href="/meetcue/zh/guide/mock-interview">模拟面试指南</a>，介绍如何不开会、通过麦克风把整个软件测一遍。</li></ul><h2 id="_0-2-1-—-2026-10-26" tabindex="-1">0.2.1 — 2026-10-26 <a class="header-anchor" href="#_0-2-1-—-2026-10-26" aria-label="Permalink to &quot;0.2.1 — 2026-10-26&quot;">​</a></h2><h3 id="修复-1" tabindex="-1">修复 <a class="header-anchor" href="#修复-1" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>会议或练习一开始，面板和 <strong>设置 › 音频</strong> 里的电平条就不再跳动，看起来像 MeetCue 在听的时候麦克风没有声音。练习也因此察觉不到你开始说话。</li></ul><h2 id="_0-2-0-—-2026-10-26" tabindex="-1">0.2.0 — 2026-10-26 <a class="header-anchor" href="#_0-2-0-—-2026-10-26" aria-label="Permalink to &quot;0.2.0 — 2026-10-26&quot;">​</a></h2><h3 id="变更" tabindex="-1">变更 <a class="header-anchor" href="#变更" aria-label="Permalink to &quot;变更&quot;">​</a></h3><ul><li>设置向导和 <strong>设置 › 供应商与费用</strong> 使用同一套方式自由填写供应商和模型：为每项任务选择供应商并填写任意模型名。供应商返回的模型名会作为输入建议；MeetCue 不再列出模型和价格，改为链接到各供应商的官方价格页。</li><li>Anthropic 可以经由网关或代理访问：在密钥旁填写接口地址即可。接口地址现在按供应商保存在 <code>providers.baseUrls</code> 中，原有的 OpenAI 兼容接口地址会保留。</li><li>用于预算统计的价格在 <strong>设置 › 供应商与费用 › 预算 › 你填写的价格</strong> 中填写。</li></ul><h3 id="修复-2" tabindex="-1">修复 <a class="header-anchor" href="#修复-2" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>在 Windows 上点按钮打开 <strong>重新运行设置向导</strong>、运行日志或其他窗口时，MeetCue 会卡死：所有窗口都无法移动，程序也无法退出。</li><li>语音识别： <ul><li>会议开始时如果还没有任何声音播放，系统声音的识别约 20 秒后就会中断并显示 <code>MC-ASR-002</code>。现在无论是否有音频都会保持连接，供应商关闭的连接也会立即重连，不必等到有声音。</li><li>供应商无法连接或响应很慢时会拖住其他一切：重试期间停止或退出最长要等一分钟，音频也会丢失。现在连接在后台进行，每个网络步骤都有时间上限。</li><li>错误提示现在会显示具体原因（例如 <code>connection timed out</code>），识别恢复后连接错误会自动消失，面板也会标出正在重连的一侧。</li><li>供应商不接受的设置现在报告为 <code>MC-ASR-004</code>，而不是网络问题（<code>MC-ASR-002</code>），也不会再每秒重试多次。</li><li>在配置了 IPv6 但实际不通的网络上，连接不再超时。</li></ul></li><li>面板上的电平条在会话开始前一直不动，麦克风在 <strong>设置 › 音频</strong> 里正常，在面板上却像没有声音。现在面板显示时，按下 <strong>开始</strong> 之前也会显示两侧电平；在你按下开始之前不会向任何地方发送内容。</li><li>麦克风只传来静音（被 Windows 隐私设置禁止或已静音）时，现在会提示 <code>MC-AUD-002</code>。</li><li>MeetCue 内部的意外错误现在会写入日志。</li></ul><h2 id="_0-1-3-—-2026-10-24" tabindex="-1">0.1.3 — 2026-10-24 <a class="header-anchor" href="#_0-1-3-—-2026-10-24" aria-label="Permalink to &quot;0.1.3 — 2026-10-24&quot;">​</a></h2><h3 id="变更-1" tabindex="-1">变更 <a class="header-anchor" href="#变更-1" aria-label="Permalink to &quot;变更&quot;">​</a></h3><ul><li>价格直接读取自 Anthropic、Soniox、Deepgram 的官网价格页，以及在模型列表中附带价格的 OpenAI 兼容接口。现在每个当前的 Claude 模型都显示价格和预计费用；只有在任何来源都没有价格的模型才链接到价格页。</li><li>Deepgram 显示当前实际收费的费率（包括限时优惠），常规费率显示在提示中。</li><li>会议进行中更换模型、密钥、语言或提示设置会立即生效：下一个问题使用新模型，语音识别切换时也不会丢掉正在说的那句话。</li><li>所有设置都可以在程序中修改：人声检测门限和句末静音（现最长 3 秒）改为滑块；<strong>通用</strong> 中新增面板形态和 <strong>重置面板位置</strong>；可 <strong>重新运行设置向导</strong>；可修改全部费用估算假设；列出你填写的价格并可 <strong>删除</strong>；可编辑练习复盘统计的口头禅。更换麦克风或人声门限在会议中也会立即生效。</li></ul><h3 id="新增-2" tabindex="-1">新增 <a class="header-anchor" href="#新增-2" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><strong>设置 › 诊断 › 运行日志</strong> 实时显示 MeetCue 在做什么：开始与暂停、两侧是否收到音频、识别出的句子、问题和错误。也可从托盘菜单和任意错误提示打开。</li></ul><h3 id="修复-3" tabindex="-1">修复 <a class="header-anchor" href="#修复-3" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>缺少密钥、模型或音频设备时，点 <strong>开始</strong> 或 <strong>继续</strong> 没有任何反应；现在会显示原因，音频启动失败时也不会留下半开的会话。</li><li>快捷键被占用等提示之前从不显示。</li><li>暂停时会议计时仍在走。</li><li>设置页面较长时，左侧标签栏会被滚走。</li><li>语音识别： <ul><li>一句话的开头经常被截掉；现在会连同说话前 0.3 秒一起发送。</li><li>连接第二次中断后，或暂停超过几秒后，本场会议的识别会彻底停止；现在暂停期间会保持连接，并在需要时自动重连。</li><li>使用 Deepgram 时，英文句子各段之间丢失空格（如 “yourexperience”）。</li><li>使用 Deepgram 且同时选择中文和英文时，英文会被送进普通话模型。现在 <strong>会议语言</strong> 中的第一个语言为主要语言，并新增“以英文为主，夹杂中文”选项。</li><li>句末静音设置被截短为 0.8 秒。</li></ul></li></ul><h2 id="_0-1-2-—-2026-10-24" tabindex="-1">0.1.2 — 2026-10-24 <a class="header-anchor" href="#_0-1-2-—-2026-10-24" aria-label="Permalink to &quot;0.1.2 — 2026-10-24&quot;">​</a></h2><h3 id="变更-2" tabindex="-1">变更 <a class="header-anchor" href="#变更-2" aria-label="Permalink to &quot;变更&quot;">​</a></h3><ul><li>价格不再内置在程序中。MeetCue 会下载对照各供应商官网核对过的<a href="/meetcue/zh/reference/pricing">价格参考</a>，保留最近一份供离线使用，并可在 <strong>设置 › 供应商与费用</strong> 中更新。</li><li>更紧凑的 <strong>模型与价格</strong> 布局：每个模型一行，显示单价和预计每小时费用，按费用排序，并标出 <strong>最省</strong> 和 <strong>最快</strong>。API 密钥每个供应商一行。</li><li>没有公开价格的模型改为链接到供应商官网价格页，不再显示 <strong>价格未知</strong>。</li></ul><h3 id="修复-4" tabindex="-1">修复 <a class="header-anchor" href="#修复-4" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>Deepgram Nova-3 之前按多语言费率计算。MeetCue 识别中文或英文时只请求单一语言，费用为每分钟 0.0077 美元。</li></ul><h3 id="新增-3" tabindex="-1">新增 <a class="header-anchor" href="#新增-3" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>Claude Sonnet 5、Claude Opus 5 和 Claude Fable 5.1 的价格。</li></ul><h2 id="_0-1-1-—-2026-10-24" tabindex="-1">0.1.1 — 2026-10-24 <a class="header-anchor" href="#_0-1-1-—-2026-10-24" aria-label="Permalink to &quot;0.1.1 — 2026-10-24&quot;">​</a></h2><h3 id="修复-5" tabindex="-1">修复 <a class="header-anchor" href="#修复-5" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>Deepgram、Anthropic 和 OpenAI 兼容接口的密钥验证失败，使用它们的会话也无法开始：此前只接入了 Soniox。</li><li>在设置向导中点 <strong>完成</strong> 后，窗口变成空白而不是关闭。</li><li>设置中的开关滑块位置偏移。</li></ul><h3 id="移除" tabindex="-1">移除 <a class="header-anchor" href="#移除" aria-label="Permalink to &quot;移除&quot;">​</a></h3><ul><li>Amazon Bedrock。要点生成请使用 Anthropic 或 OpenAI 兼容接口。</li></ul><h2 id="_0-1-0-—-2026-10-23" tabindex="-1">0.1.0 — 2026-10-23 <a class="header-anchor" href="#_0-1-0-—-2026-10-23" aria-label="Permalink to &quot;0.1.0 — 2026-10-23&quot;">​</a></h2><h3 id="新增-4" tabindex="-1">新增 <a class="header-anchor" href="#新增-4" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>会议模式：实时问题检测与提前触发，约一秒半内给出编号要点，问题队列，已讲要点打勾。</li><li>不抢焦点的悬浮面板，支持完整与迷你两种形态、鼠标穿透和共享屏幕时隐藏。</li><li>语音识别支持 Soniox 和 Deepgram；要点生成支持 Anthropic、Amazon Bedrock 和 OpenAI 兼容接口。</li><li>延迟探测：自动选择端点、估算费用并对组合排序。</li><li>价格表、用量统计、预算提醒和 CSV 导出。</li><li>练习模式：导入字幕和问题列表并在预览中编辑，用系统语音朗读问题，支持真实识别和模拟延迟、追问、四档提示难度，以及可导出为 Markdown 的复盘报告。</li><li>支持 txt、md、docx 和 pdf 格式的会前资料。</li><li>中英双语界面与文档。</li><li>带解决办法链接的错误码、诊断信息导出、<code>--demo</code> 与 <code>--self-test</code>。</li></ul>',41)])])}const b=e(o,[["render",t]]);export{g as __pageData,b as default};
